namespace sv_ed1af5dd3b634dbaacd567fbc30a2150.Services;

public enum Theme
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped service holding per-circuit theme state.
/// All interactive components in the same circuit share one instance.
/// </summary>
public class ThemeService
{
    private Theme _theme = Theme.System;
    private string _accentColor = "#0d6efd";

    public Theme CurrentTheme
    {
        get => _theme;
        set
        {
            if (_theme == value) return;
            _theme = value;
            NotifyChanged();
        }
    }

    public string AccentColor
    {
        get => _accentColor;
        set
        {
            if (_accentColor == value) return;
            _accentColor = value;
            NotifyChanged();
        }
    }

    public event Action? OnChange;

    private void NotifyChanged() => OnChange?.Invoke();
}

@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService ThemeService

<span class="theme-indicator" style="color: @ThemeService.AccentColor;" title="Current theme">
    @GetThemeIcon() @ThemeService.CurrentTheme
</span>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += HandleThemeChanged;
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    private string GetThemeIcon() => ThemeService.CurrentTheme switch
    {
        Theme.Light => "☀️",
        Theme.Dark => "🌙",
        Theme.System => "💻",
        _ => "💻"
    };

    public void Dispose()
    {
        ThemeService.OnChange -= HandleThemeChanged;
    }
}

@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService ThemeService

<div class="theme-toggle">
    <button class="btn btn-sm @GetButtonClass(Theme.Light)" @onclick="() => SetTheme(Theme.Light)">☀️ Light</button>
    <button class="btn btn-sm @GetButtonClass(Theme.Dark)" @onclick="() => SetTheme(Theme.Dark)">🌙 Dark</button>
    <button class="btn btn-sm @GetButtonClass(Theme.System)" @onclick="() => SetTheme(Theme.System)">💻 System</button>
</div>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += HandleThemeChanged;
    }

    private void SetTheme(Theme theme)
    {
        ThemeService.CurrentTheme = theme;
    }

    private string GetButtonClass(Theme theme) =>
        ThemeService.CurrentTheme == theme ? "btn-primary" : "btn-outline-secondary";

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        ThemeService.OnChange -= HandleThemeChanged;
    }
}

@page "/settings"
@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService ThemeService

<PageTitle>Settings</PageTitle>

<h3>User Preferences</h3>

<div class="card mt-3" style="max-width: 500px;">
    <div class="card-body">
        <h5 class="card-title">Theme</h5>
        <ThemeToggle />

        <h5 class="card-title mt-4">Accent Color</h5>
        <div class="d-flex align-items-center gap-3">
            <input type="color"
                   class="form-control form-control-color"
                   value="@ThemeService.AccentColor"
                   @onchange="OnAccentColorChanged" />
            <span style="color: @ThemeService.AccentColor; font-weight: bold;">
                @ThemeService.AccentColor
            </span>
        </div>

        <div class="mt-4 p-3 border rounded" style="border-color: @ThemeService.AccentColor !important;">
            <strong>Preview:</strong> Current theme is <em>@ThemeService.CurrentTheme</em>
            with accent <span style="color: @ThemeService.AccentColor;">@ThemeService.AccentColor</span>
        </div>
    </div>
</div>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += HandleThemeChanged;
    }

    private void OnAccentColorChanged(ChangeEventArgs e)
    {
        ThemeService.AccentColor = e.Value?.ToString() ?? "#0d6efd";
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        ThemeService.OnChange -= HandleThemeChanged;
    }
}

